SELECT COUNT(*) FROM "title" AS v1, "infoVertex" AS v2, "castInfoVertex" AS v4, "title_infoEdge_infoVertex" AS e1, "title_movieCompanies_companyName" AS e2, "castInfoVertex_castInfoEdge_title" AS e3 WHERE e1.src = v1.id AND e1.dst = v2.id AND e2.src = v1.id AND e3.src = v4.id AND e3.dst = v1.id AND v4."role_id" = 2 AND v2."info_type_id" = 16 AND v1."production_year" > 2005 AND v1."production_year" < 2009;
